<script setup lang="ts">
import { benefitText } from '@/shared/i18n'
import {computed,ref} from 'vue'
import {AlertTriangle,ArrowUpRight,Search,Download,ShieldCheck,Info,Users} from 'lucide-vue-next'
import {data,latin,num,money,sum,auditTitles,saveCSV,type AuditCase} from './data'
import RegionMap from './RegionMap.vue'
import MetricValue from './MetricValue.vue'
import RiskScopeAnalysis from './RiskScopeAnalysis.vue'
const props=defineProps<{initial?:number;reviewRefresh?:number}>()
const emit=defineEmits<{open:[{item:AuditCase;category:number}];family:[string]}>()
const selected=ref(props.initial??0),region=ref(''),query=ref(''),reviewState=ref('')
const signal=computed(()=>data.audit[selected.value]!)
const regions=computed(()=>data.regions.map((name,i)=>{const original=data.regionMap.indexOf(i);return {name,i,count:signal.value.reg[original]?.[0]??0,amount:signal.value.reg[original]?.[1]??0}}))
const reviews = computed(() => {
  const records = new Map<number, { state?: string; owner?: string; due?: string }>()
  // The parent increments the version after saving a drawer review.
  if (props.reviewRefresh === undefined) return records
  for (const item of signal.value.smp) {
    try {
      const stored = JSON.parse(localStorage.getItem('nasp-social-review-'+ selected.value + '-' + item.id) ?? 'null')
      if (stored) records.set(item.id, stored)
    } catch { /* Cases are still visible if review notes are unavailable. */ }
  }
  return records
})
const cases = computed(() => signal.value.smp.filter(item =>
  (!region.value || data.regionMap[item.ri] === +region.value) &&
  (!query.value || String(item.id).includes(query.value)) &&
  (!reviewState.value || (reviews.value.get(item.id)?.state ?? 'Ko‘rib chiqilmagan') === reviewState.value),
))
const gapLines=computed(()=>data.finance.filter(x=>x.plan&&x.id!=='a17').map(x=>({...x,ratio:x.s/x.plan!*100})).sort((a,b)=>a.ratio-b.ratio))
const additional=[{title:'Vafot etgan shaxs nomiga davom etgan to‘lov',source:'FHDYO reyestri',count:412,amount:1.9},{title:'Bir maqsadda ikki idoradan to‘lov',source:'IHMA va Pensiya jamg‘armasi',count:1287,amount:6.4},{title:'Daromad mezondan oshgan, ko‘mak davom etmoqda',source:'Soliq qo‘mitasi',count:3560,amount:11.2},{title:'Huquqi bor, lekin chora tayinlanmagan',source:'Ijtimoiy reyestr va nogironlik bazasi',count:18940,amount:null}]
function download(){saveCSV('Nazorat_holatlari.csv',[['Kategoriya','Kod','Hudud','Yillik summa'],...cases.value.map(x=>[auditTitles[selected.value]!,x.id,latin(data.regions[data.regionMap[x.ri]!]),x.s??sum((x.m??[]).flatMap(([,v])=>v))])])}
</script>
<template><div class="audit-view np-section-stack"><RiskScopeAnalysis :selected="selected" @category="selected=$event;region='';query=''" @region="region=$event" @family="emit('family',$event)" /><Teleport defer to="#support-filter-fields"><label>{{ benefitText("Signal turi") }}<select v-model.number="selected"><option v-for="(name,i) in auditTitles" :key="name" :value="i">{{ benefitText(name) }}</option></select></label><label>{{ benefitText('Ko‘rib chiqish holati') }}<select v-model="reviewState">
  <option value="">{{ benefitText('Barcha holatlar') }}</option>
  <option v-for="status in ['Ko‘rib chiqilmagan','Tekshirilmoqda','Qo‘shimcha dalil kerak','Tekshiruv qaydi tayyor']" :key="status" :value="status">{{ benefitText(status) }}</option>
</select></label></Teleport><div class="audit-overview"><article><span class="audit-overview-icon"><ShieldCheck :size="22"/></span><div><small>{{ benefitText("Tekshirilgan yozuvlar") }}</small><b><MetricValue :value="data.demographics.rows"/></b></div></article><article><span class="audit-overview-icon red"><AlertTriangle :size="22"/></span><div><small>{{ benefitText("Ikki turdagi ortiqcha to‘lov signali") }}</small><b>549 <span>{{ benefitText("mln so‘m") }}</span></b></div></article><article><span class="audit-overview-icon green"><Users :size="22"/></span><div><small>{{ benefitText("Nafaqa oluvchilar") }}</small><b>{{ num(data.demographics.persons) }}</b></div></article></div><div class="audit-categories"><button v-for="(item,i) in data.audit" :key="item.k" :class="['audit-category',{selected:selected===i},i<3?'red':i===3?'amber':'blue']" @click="selected=i;region='';query=''"><span>{{ benefitText(i<2?'Ortiqcha to‘lov':i<4?'Tekshirish zarur':'Ma’lumot uchun') }}</span><strong><MetricValue :value="item.n"/></strong><h3>{{ benefitText(auditTitles[i]) }}</h3><small>{{ benefitText(money((item.over??item.s)*1e9)) }}{{ benefitText(" so‘m ") }}<ArrowUpRight :size="13"/></small></button></div><div class="audit-columns"><section class="np-card"><div class="np-card-heading"><div><h3>{{ benefitText("Hududlar bo‘yicha taqsimot") }}</h3><p>{{ benefitText(auditTitles[selected]) }}</p></div><span class="np-tag blue">{{ benefitText("14 hudud") }}</span></div><RegionMap :values="regions.map(x=>x.count)" :selected="region" count @select="region=$event"/><Teleport defer to="#support-filter-fields"><div class="region-chips"><button v-for="row in regions" :key="row.i" :class="{selected:region===String(row.i)}" @click="region=region===String(row.i)?'':String(row.i)"><span>{{ benefitText(benefitText(row.name).replace(' viloyati','').replace(' Respublikasi','')) }}</span><b>{{ num(row.count) }}</b></button></div></Teleport></section><section class="np-card audit-explanation"><span class="np-tag" :class="selected<3?'red':selected===3?'amber':'blue'">{{ benefitText(signal.lt) }}</span><h3>{{ benefitText(benefitText(signal.title)||auditTitles[selected]) }}</h3><p>{{ benefitText(signal.why) }}</p><div class="audit-source"><Info :size="16"/><span>{{ benefitText(signal.src) }}</span></div><p class="np-note">{{ benefitText("Bir shaxs bir nechta hududda hisobga olingan bo‘lishi mumkin.") }}</p></section></div><section class="np-card"><div class="np-toolbar"><div><h3>{{ benefitText("Tekshirish uchun holatlar") }}</h3><p>{{ benefitText(region===''?'Respublika':benefitText(data.regions[+region])) }}{{ benefitText(" · manbadan ") }}{{ benefitText(cases.length) }}{{ benefitText(" ta namunaviy yozuv") }}</p></div><Teleport defer to="#support-filter-fields"><label class="np-search"><Search :size="15"/><input v-model="query" :placeholder="benefitText('Holat kodi')" :aria-label="benefitText('Nazorat kodi')"/></label></Teleport><button class="np-button" @click="download"><Download :size="14"/>{{ benefitText("Eksport") }}</button></div><div class="np-table-wrap"><table class="np-table"><thead><tr><th>{{ benefitText("Holat kodi") }}</th><th>{{ benefitText("Hudud") }}</th><th>{{ benefitText("Nafaqa / ko‘lam") }}</th><th>{{ benefitText("Yillik summa") }}</th><th>{{ benefitText("Holat") }}</th><th></th></tr></thead><tbody><tr v-for="item in cases" :key="item.id"><td><button class="text-button" @click="emit('open',{item,category:selected})">#{{ benefitText(item.id) }}</button><small v-if="item.age">{{ benefitText(item.age) }}{{ benefitText(" yosh") }}</small></td><td>{{ benefitText(data.regions[data.regionMap[item.ri]!]) }}</td><td>{{ benefitText(selected===3?(item.n+' oluvchi'):(item.m??[]).map(([t])=>benefitText(data.benefitTypes[t])).join(', ')) }}</td><td>{{ benefitText(money(item.s??sum((item.m??[]).flatMap(([,v])=>v)))) }}{{ benefitText(" so‘m") }}</td><td><span class="np-tag" :class="selected<3?'red':selected===3?'amber':'blue'">{{ benefitText(signal.lt) }}</span></td><td><button class="np-button" @click="emit('open',{item,category:selected})">{{ benefitText("Dalil ") }}<ArrowUpRight :size="13"/></button></td></tr><tr v-if="!cases.length"><td colspan="6" class="np-empty">{{ benefitText("Tanlangan hudud uchun batafsil yozuv mavjud emas.") }}</td></tr></tbody></table></div></section><div class="audit-columns lower"><section class="np-card"><h3>{{ benefitText("Vedomost ijrosi") }}</h3><p>{{ benefitText("2025-yil · to‘lanmagan qism ") }}{{ benefitText(money(sum(gapLines.map(x=>Math.max(0,x.plan!-x.s)))*1e9)) }}{{ benefitText(" so‘m") }}</p><div v-for="line in gapLines" :key="line.id" class="execution-bar"><div><span>{{ benefitText(line.n) }}</span><b :class="line.ratio<90?'danger-text':'success-text'">{{ num(line.ratio,1) }}%</b></div><i><em :style="{width:Math.min(100,line.ratio)+'%'}"/></i><small>{{ benefitText(money(line.s*1e9)) }} / {{ benefitText(money(line.plan!*1e9)) }}{{ benefitText(" so‘m") }}</small></div></section><section class="np-card"><h3>{{ benefitText("Oila va to‘lovlar kesimi") }}</h3><div class="audit-family-stat"><strong>{{ num(data.familyAudit.multi) }}</strong><span>{{ benefitText("Ikki va undan ortiq a’zosi nafaqa oladigan oilalar") }}</span></div><div class="audit-family-stat"><strong>{{ num(data.familyAudit.n) }}</strong><span>{{ benefitText("Yiliga 40 mln so‘mdan ko‘p ko‘mak olgan oilalar") }}</span></div><h3>{{ benefitText("To‘lov kanallari") }}</h3><div v-for="[name,count] in data.demographics.card" :key="name" class="audit-channel"><span>{{ benefitText(name) }}</span><b>{{ num(count) }}</b></div><p class="np-note">{{ benefitText("Komissiya: ") }}{{ num(data.demographics.comm,2) }}{{ benefitText(" mlrd so‘m. Kanal sonlari — to‘lov yozuvlari.") }}</p><h3>{{ benefitText("Birga uchraydigan nafaqa turlari") }}</h3><div v-for="[types,count] in data.demographics.pairs" :key="types.join('-')" class="audit-channel"><span>{{ benefitText(types.map(i=>benefitText(data.benefitTypes[i])).join(' + ')) }}</span><b>{{ num(count) }}</b></div></section></div><section class="np-card"><div class="np-card-heading"><h3>{{ benefitText("Idoralararo solishtirish imkoniyatlari") }}</h3><span class="np-tag amber">{{ benefitText("Namunaviy ko‘rsatkichlar") }}</span></div><div class="np-table-wrap"><table class="np-table"><thead><tr><th>{{ benefitText("Signal") }}</th><th>{{ benefitText("Solishtirish manbasi") }}</th><th>{{ benefitText("Shaxslar") }}</th><th>{{ benefitText("Summa") }}</th></tr></thead><tbody><tr v-for="item in additional" :key="item.title"><td>{{ benefitText(item.title) }}</td><td>{{ benefitText(item.source) }}</td><td>{{ num(item.count) }}</td><td>{{ benefitText(item.amount===null?'—':item.amount+' mlrd so‘m') }}</td></tr></tbody></table></div></section></div></template>
<style scoped>.audit-overview{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-bottom:20px}.audit-overview article{display:flex;align-items:center;gap:14px;background:var(--card);border:1px solid var(--border);border-radius:12px;padding:18px}.audit-overview-icon{height:45px;width:45px;display:grid;place-items:center;border-radius:12px;background:#edf3fe;color:#4070d4}.audit-overview-icon.red{background:#fff0ed;color:#d06a56}.audit-overview-icon.green{background:#e9f7f2;color:#1f9f7b}.audit-overview small{color:var(--muted-foreground);font-size:11px;display:block}.audit-overview b{font-size:23px;color:#354c70;display:block;margin-top:3px}.audit-overview b>span{font-size:12px}.audit-categories{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-bottom:22px}.audit-category{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:16px;text-align:left;transition:all .2s;display:flex;flex-direction:column;gap:10px;--tone:#426bc7}.audit-category.red{--tone:#cf6957}.audit-category.amber{--tone:#bf8a37}.audit-category.selected{border-color:var(--tone);box-shadow:0 0 0 2px color-mix(in srgb,var(--tone) 9%,transparent)}.audit-category>span{font-size:11px;color:var(--tone)}.audit-category strong{font-size:29px;color:var(--tone);font-weight:750}.audit-category h3{font-size:11px;font-weight:600;line-height:1.6}.audit-category small{font-size:11px;color:var(--muted-foreground);display:flex;align-items:center;justify-content:space-between;margin-top:auto}.audit-columns{display:grid;grid-template-columns:1.15fr 1fr;gap:20px;margin-bottom:20px}.audit-columns.lower{margin-top:20px}.audit-explanation h3{font-size:17px;line-height:1.6;margin:18px 0 10px}.audit-explanation>p{font-size:12px;color:var(--muted-foreground);line-height:1.7}.audit-source{display:flex;gap:9px;font-size:11px;color:var(--muted-foreground);padding:14px;background:var(--muted);border-radius:8px;margin:18px 0}.audit-source svg{flex-shrink:0}.audit-next{display:grid;gap:20px}.audit-next li{display:flex;gap:13px}.audit-next li>span{background:#f0f4fc;color:#4470d3;font-size:12px;width:28px;height:28px;border-radius:50%;display:grid;place-items:center;flex-shrink:0}.audit-next b{font-size:12px}.audit-next p{font-size:11px;color:var(--muted-foreground);margin-top:4px}.region-chips{display:grid;grid-template-columns:repeat(2,1fr);gap:5px}.region-chips button{display:flex;justify-content:space-between;gap:8px;padding:6px 8px;font-size:11px;border-radius:6px;color:var(--muted-foreground)}.region-chips button.selected{background:#edf3ff;color:var(--primary)}.execution-bar{margin:16px 0}.execution-bar>div{display:flex;gap:15px;justify-content:space-between;font-size:11px}.execution-bar>div>span{color:var(--muted-foreground);max-width:80%}.execution-bar>i{display:block;height:5px;background:#eef2f8;margin:7px 0;border-radius:5px}.execution-bar em{display:block;height:100%;border-radius:5px;background:#7197ea;transition:width .6s}.execution-bar small{font-size:11px;color:var(--muted-foreground)}.audit-family-stat{border-bottom:1px solid var(--border);padding:20px 0;display:flex;gap:20px;align-items:center}.audit-family-stat strong{font-size:27px;color:#3872b7}.audit-family-stat span{font-size:11px;color:var(--muted-foreground)}.audit-channel{display:flex;gap:16px;justify-content:space-between;padding:10px 0;font-size:11px;color:var(--muted-foreground);border-bottom:1px solid var(--border)}.audit-channel b{color:#536e98}.audit-columns h3:not(:first-child){margin-top:25px}@media(max-width:1150px){.audit-categories{grid-template-columns:repeat(3,1fr)}}@media(max-width:800px){.audit-columns{grid-template-columns:1fr}.audit-overview{grid-template-columns:1fr}.audit-categories{grid-template-columns:1fr 1fr}}</style>
